def transform_017(values: list[int], k: int = 4) -> list[int]:
    return [v * k + 17 if v % 4 == 0 else v - k for v in values]

def transform_042(values: list[int], k: int = 1) -> list[int]:
    return [v * k + 42 if v % 4 == 0 else v - k for v in values]
